{{term:函数}}可以接收**{{term:参数}}**（输入），然后根据{{term:参数}}做不同的事：
```js
function introduce(composer, piece) {
  return `${composer}创作了《${piece}》。`;
}
let result1 = introduce("肖邦", "夜曲");
let result2 = introduce("莫扎特", "魔笛");
```
- `composer` 和 `piece` 是**{{term:参数}}**——像{{term:函数}}接收的输入
- `return` 把结果**返回**——像{{term:函数}}给出的输出
- 同样一个 `introduce` {{term:函数}}，传入不同的作曲家，得到不同的句子
> 💡 关于 `this`：在普通{{term:函数}}中，`this` 指向"谁调用了这个{{term:函数}}"。比如 `button.addEventListener("click", handleClick)` 中，`handleClick` 里的 `this` 指向被点击的 `button`。后面学到{{term:事件}}和对象时你会更深入地理解它。

下面的代码定义了一个 `createCard` {{term:函数}}，它接收作曲家信息并返回 {{term:HTML}} 字符串：
```js
// function：定义一个函数，像"乐谱模板"——给参数就能生成结果
function createCard(composer, period, piece) {
  return `                         // return：把结果"返回"给调用者
    <div class="card">
      <h2>${composer}</h2>
      <p>时期：${period}</p>
      <p>代表作：《${piece}》</p>
    </div>
  `;
}
// 调用函数：传入不同的参数，得到不同的卡片
let html = createCard("巴赫", "巴洛克", "赋格的艺术");
let html2 = createCard("德彪西", "印象派", "月光");
```
切换到 {{term:JS}} {{term:标签}}页看看{{term:函数}}怎么生成页面的三张卡片。

:::step{purpose="让你理解{{term:函数}}调用的核心：同一个{{term:函数}}，传入不同的{{term:参数}}，产生不同的输出。就像同一个旋律动机，用钢琴弹和用提琴拉，效果不同但结构一样——这就是{{term:函数}}的复用之美。" expected="页面上对应卡片的名字、时期、代表作都变成了你新输入的作曲家信息，其他两张卡片保持不变。{{term:函数}}本身一行都没改，只是换了个「{{term:参数}}」。"}
修改已有的 `createCard()` 调用，把作曲家名字换成你喜欢的作曲家（如把「巴赫」改成「拉赫玛尼诺夫」），同时更新时期和代表作{{term:参数}}
:::

:::step{purpose="让你体验「调用一次{{term:函数}}就多一张卡片」的便利——不需要重新写整段 {{term:HTML}} 拼接逻辑，只需一行{{term:函数}}调用。这正是{{term:函数}}的核心价值：封装重复逻辑，一处定义，处处使用。" expected="页面上从 3 张卡片变成 4 张，新增的卡片和其他卡片{{term:样式}}完全一致，说明{{term:函数}}正确生成了 {{term:HTML}} 结构。你创造了一张全新的卡片！"}
新增一行 `createCard()` 调用，创建第四张卡片。比如：`html += createCard("舒伯特", "浪漫主义", "未完成交响曲");`，注意用 `+=` 追加到 {{term:html}} {{term:变量}}中
:::

:::step{purpose="练习修改{{term:函数}}定义——增加{{term:参数}}意味着{{term:函数}}的能力增强了。就像给一段旋律加一个变奏：原有的结构不变，但增加了新的表现力。理解「改一处定义，所有调用点都受益」这个设计思想。" expected="所有卡片都会多出一行国籍信息，而你只需要改{{term:函数}}的定义和调用{{term:参数}}——这就是{{term:函数}}作为「单一真相来源」的力量。"}
挑战：给 `createCard` {{term:函数}}增加一个 `country` {{term:参数}}。先在{{term:函数}}定义的{{term:模板字符串}}中添加一行 `<p>国籍：${country}</p>`，然后在每次调用时传入国籍{{term:参数}}（如 `"德国"`、`"奥地利"`、`"法国"`）
:::

