// 实时输入事件
let inputEl = document.querySelector("#nameInput");
let liveText = document.querySelector("#liveText");
inputEl.addEventListener("input", function(event) {
  let val = event.target.value;
  liveText.textContent = val || "---";
});
// 鼠标悬停事件
let hoverCard = document.querySelector("#hoverCard");
hoverCard.addEventListener("mouseenter", function() {
  hoverCard.style.borderColor = "#C9A96E";
  hoverCard.style.background = "#FFF8EC";
});
hoverCard.addEventListener("mouseleave", function() {
  hoverCard.style.borderColor = "#D4C5A9";
  hoverCard.style.background = "#FFFAF2";
});
// 键盘事件
let keyHint = document.querySelector("#keyHint");
document.addEventListener("keydown", function(event) {
  if (event.key === "Enter") {
    keyHint.textContent = "🎹 你按了回车键！";
    keyHint.style.color = "#8B2E2E";
  } else {
    keyHint.textContent = `你按下了: "${event.key}"`;
    keyHint.style.color = "#C9A96E";
  }
});

body.content:
在你的 music-collection-vue 项目中：
```bash
# 安装依赖
npm install -D eslint prettier eslint-plugin-vue eslint-config-prettier
# ESLint 配置（eslint.config.js）
import pluginVue from 'eslint-plugin-vue'
export default [
  ...pluginVue.configs['flat/recommended'],
  {
    rules: {
      'vue/multi-word-component-names': 'off',
      'no-console': 'warn'
    }
  }
]
# VS Code 设置（.vscode/settings.json）
{
  "editor.formatOnSave": true,
  "editor.defaultFormatter": "esbenp.prettier-vscode",
  "editor.codeActionsOnSave": {
    "source.fixAll.eslint": true
  }
}
```
配置完成后，每次保存文件：Prettier 先格式化，ESLint 再检查和自动修复。你的代码会像印刷出来的乐谱一样整齐。

为什么不用普通{{term:函数}}？
```js
// ❌ 普通函数：每次模板重渲染都重新计算
function getClassical() {
  return pieces.value.filter(p => p.period === '古典主义')
}
// ✅ computed：只在 pieces 变化时才重新计算
const classicalPieces = computed(() => {
  return pieces.value.filter(p => p.period === '古典主义')
})
```
就像乐谱翻页：{{term:函数}}式每次都从头到尾唱一遍来找古典曲目；{{term:computed}} 像在谱子上贴了{{term:标签}}——曲目单不变就不用重新翻。

`watch` 用于"当某个值变了，我要做点什么"——比如保存到 {{term:localStorage}}、发{{term:请求}}：
```vue
<script setup>
import { ref, watch } from 'vue'
const searchKeyword = ref('')
const results = ref([])
// watch：监测 keyword 变化，执行副作用
watch(searchKeyword, async (newVal, oldVal) => {
  if (newVal.length === 0) {
    results.value = []
    return
  }
  console.log(\`搜索：\${oldVal} → \${newVal}\`)
  results.value = await searchAPI(newVal)
})
</script>
```
{{term:watch}}` 适合：
- 保存数据到 {{term:localStorage}}
- 搜索/筛选触发 {{term:API}} {{term:请求}}
- 某个值变化时更新页面标题
- 数据变化时触发动画

:::step{purpose="{{term:computed}} 从已有数据自动派生出新值并自带{{term:缓存}}。你只需要声明筛选逻辑（{{term:filter}}），{{term:Vue}} 在{{term:依赖}}（曲目列表或选中时期）变化时自动重新计算。这在合奏篇中需要你手动写筛选逻辑 + 手动调用 {{term:render}}——现在一行 {{term:computed}} 搞定。" expected="选择不同时期，曲目列表自动过滤，只显示匹配的曲目。"}
添加 {{term:computed}}：根据用户选择的时期（period）筛选曲目列表
:::

:::step{purpose="{{term:watch}} 用于在数据变化时执行副作用（如保存、发{{term:请求}}、操作 {{term:DOM}}）。这里用它监听曲目列表，自动将数据序列化到 {{term:localStorage}}——用户刷新页面后数据不会丢失。在合奏篇中你需要手动在每个修改点调用保存{{term:函数}}，现在只需一个 {{term:watch}}。" expected="添加/删除曲目后刷新页面，数据仍然存在（自动从 {{term:localStorage}} 恢复）。"}
添加 {{term:watch}}：当曲目列表变化时，自动保存到 {{term:localStorage}}
:::

{{term:防抖}}的核心：每次触发时清除上一个定时器，重新计时。
```js
function debounce(fn, delay = 300) {
  let timer = null
  return function(...args) {
    clearTimeout(timer)            // 清除上次的定时器
    timer = setTimeout(() => {     // 重新计时
      fn.apply(this, args)
    }, delay)
  }
}
// 使用
const search = debounce(async (keyword) => {
  console.log('搜索：', keyword)
  const result = await api.get(\`/search?q=\${keyword}\`)
  displayResults(result)
}, 500)
// 用户在输入框打字
input.addEventListener('input', (e) => {
  search(e.target.value)  // 停止输入 500ms 后才真正搜索
})
```

:::step{purpose="{{term:防抖}}利用闭包（Closure）让内{{term:层}}{{term:函数}}记住并访问外{{term:层}}的 timer {{term:变量}}。每次调用时先清除上次的定时器，再启动新的——就像有人在电梯关门键上不停按，每次按都重新计时，直到没人按了才真正关门。" expected="debounce 返回一个新{{term:函数}}，这个{{term:函数}}在连续被调用时，只有最后一次调用（经过 delay 毫秒后）会触发 fn。"}
在 debounce 内部声明 {{term:let}} timer = {{term:null}}（闭包{{term:变量}}），返回的{{term:函数}}中先 clearTimeout(timer)，再 timer = {{term:setTimeout}}(() => fn(...args), delay)
:::

:::step{purpose="{{term:防抖}}{{term:函数}}是一个\"装饰器\"——它接收一个{{term:函数}}，返回一个被\"{{term:防抖}}化\"的新{{term:函数}}。原{{term:函数}}的功能不变，只是增加了\"等待稳定后再执行\"的行为。这种包装模式在工程中非常常见。" expected="debouncedSearch 的行为与 searchAPI 相同，但连续快速调用时只有最后一次会生效。"}
用 {{term:const}} debouncedSearch = debounce(searchAPI, 500) 包装搜索{{term:函数}}
:::

:::step{purpose="在搜索场景中，用户在输入框快速打字时，debounce 避免了每个字符都发一次网络{{term:请求}}——只在用户停下来 500ms 后才真正搜索。这对节省流量和服务器资源至关重要。" expected="500ms 后控制台只输出一次 \"🔍 发送搜索{{term:请求}}：贝多芬\"，前两次调用被取消了。"}
连续快速调用 debouncedSearch("贝") → debouncedSearch("贝多") → debouncedSearch("贝多芬")，验证控制台只输出一次搜索{{term:请求}}
:::

