// 曲目数据
let pieces = [
  { name: "布兰登堡协奏曲", period: "巴洛克" },
  { name: "费加罗的婚礼序曲", period: "古典主义" },
  { name: "月光奏鸣曲", period: "古典主义" }
];
let listEl = document.querySelector("#cardList");
// 当前用 innerHTML 渲染——你的任务：改成 createElement + appendChild
function render() {
  let html = "";
  for (let i = 0; i < pieces.length; i++) {
    html += '<div class="card"><h3>' + pieces[i].name + '</h3><span class="tag">' + pieces[i].period + '</span></div>';
  }
  listEl.innerHTML = html;
}
render();
// 添加随机曲目
document.querySelector("#addBtn").addEventListener("click", function() {
  let randomPieces = [
    { name: "G弦上的咏叹调", period: "巴洛克" },
    { name: "第40号交响曲", period: "古典主义" },
    { name: "夜曲 Op.9 No.2", period: "浪漫主义" }
  ];
  let pick = randomPieces[Math.floor(Math.random() * randomPieces.length)];
  pieces.push(pick);
  render();
});

body.content:
还记得 {{term:transition}} 吗？它只能在两个状态之间平滑过渡（比如 {{term:hover}} 前 → {{term:hover}} 后）。{{term:@keyframes}} 让你定义**任意多个关键帧**，创建更复杂的动画：
```css
@keyframes swing {
  0%   { transform: rotate(0deg); }
  25%  { transform: rotate(5deg); }
  50%  { transform: rotate(0deg); }
  75%  { transform: rotate(-5deg); }
  100% { transform: rotate(0deg); }
}
```百分比代表动画的进度（0% = 开始，100% = 结束）
- 也可以用 {{term:from}}（= 0%）和 to（= 100%）
- 每个关键帧可以定义任意多个 {{term:CSS}} {{term:属性}}
就像乐谱中精确标注了每个小节的力度和表情记号——你掌控着动画的每一帧。

{{term:transform}} 不止能用在 {{term:transition}} 中，配合 {{term:@keyframes}} 效果更丰富：
```css
/* 2D 变换 */
transform: translateX(100px);    /* 水平移动 */
transform: translateY(-20px);    /* 垂直移动 */
transform: scale(1.2);           /* 放大到 1.2 倍 */
transform: rotate(45deg);        /* 顺时针旋转 45° */
transform: skewX(10deg);         /* 水平倾斜 */
/* 组合变换（空格分隔，顺序很重要！） */
transform: translateX(100px) rotate(45deg) scale(1.1);
/* 设置旋转中心点 */
transform-origin: center center;  /* 默认是元素中心 */
transform-origin: top left;       /* 改为左上角 */
```3D 变换（需要 perspective 才能看到深度效果）：
```css
.container {
  perspective: 600px;  /* 透视距离——越小越夸张 */
}
.card {
  transform: rotateY(30deg);   /* 绕 Y 轴旋转 */
  transform: rotateX(15deg);   /* 绕 X 轴翻转 */
}
```就像指挥要求小提琴组不只拉动琴弓（{{term:translate}}），还要微微转动琴身（{{term:rotate}}）来控制音色。

下面的代码展示了三种经典动画效果：
```css
/* 摇摆——像节拍器 */
@keyframes swing {
  0%, 100% { transform: rotate(-3deg); }
  50% { transform: rotate(3deg); }
}
/* 淡入上浮——像幕布升起 */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
/* 心跳——缩放+透明度脉动 */
@keyframes heartbeat {
  0%, 100% { transform: scale(1); }
  15% { transform: scale(1.15); }
  30% { transform: scale(1); }
  45% { transform: scale(1.1); }
  60% { transform: scale(1); }
}
```看预览区——三张卡片各自执行不同的动画，播放/暂停按钮可以控制动画状态。

:::step{purpose="修改 `@keyframes` 中关键帧的 `rotate` 值直接改变动画幅度。值越大，摇摆越猛。" expected="第一张卡片的摇摆幅度明显更大了。动画的幅度由关键帧中的{{term:属性}}值决定。"}
把 `swing` 动画的 `rotate` 角度从 `3deg` 改成 `8deg`，看摇摆幅度变大
:::

:::step{purpose="增加位移距离让动画的轨迹更长。`translateY` 的正值表示向下移动。" expected="第二张卡片的淡入上浮动画从更远的地方飘过来。修改值让动画效果发生了明显变化。"}
修改 `fadeInUp` 的 `translateY` 从 `30px` 改成 `60px`
:::

:::step{purpose="`animation-duration` 控制完整周期的时间。改小后心跳更快更急促。" expected="心跳动画明显加速了。duration 是控制动画节奏最直接的{{term:参数}}。"}
给 `heartbeat` 的 `animation-duration` 从 `1.5s` 改成 `0.8s`
:::

:::step{purpose="三个关键{{term:参数}}组合：`rotate` 旋转、`linear` 匀速（不是默认的 {{term:ease}}）、`infinite` 无限循环——这就是黑胶唱片的视觉效果。" expected="{{term:元素}}持续匀速旋转，不会停下。你创造了第一个真正独立的 {{term:CSS}} 动画。"}
挑战：写一个唱片旋转动画（`rotate` + `infinite` + `linear`）
:::

:::step{purpose="`animation-fill-mode: forwards` 让动画结束后停在最后一帧；`none` 则回到初始状态。先改 `infinite` 为 `1`（只播一次）才能看出区别。" expected="`forwards` 时动画结束后{{term:元素}}停在终点位置不闪回；`none` 时播完后会闪回起点。"}
挑战：把 `fadeInUp` 的 `fill-mode` 改成 `forwards` 和 `none`，对比差异
:::

