{{term:import}} vue {{term:from}} "@vitejs/{{term:plugin}}-vue";
{{term:export}} default defineConfig({
  plugins: [vue()],
  define: {
    __APP_VERSION__: {{term:JSON}}.stringify("1.0.0"),
    __BUILD_TIME__: {{term:JSON}}.stringify({{term:new}} {{term:Date}}().toISOString()),
    __AUTHOR__: {{term:JSON}}.stringify("你的名字"),
  },
});</{{term:code}}></{{term:pre}}><p>在代码中直接使用：<{{term:code}}>console.log("版本：", __APP_VERSION__);</{{term:code}}></p><p><{{term:code}}>define</{{term:code}}> 在编译时替换，适合版本号等固定值；<{{term:code}}>{{term:import}}.{{term:meta}}.env.VITE_*</{{term:code}}> 运行时读取，适合环境相关值。</p></{{term:div}}></{{term:details}}>[[/{{term:html}}]]

:::step{purpose="{{term:v-for}} 是列表{{term:渲染}}的核心指令。将数据{{term:数组}}中的每一项映射为可视化的卡片，是整个应用的基础骨架。这一步验证你对{{term:响应式}}数据绑定和列表{{term:渲染}}的掌握。" expected="页面上整齐排列着多张曲目卡片，每张显示曲名、作曲家和时期。"}
【基础1】用 {{term:v-for}} 展示曲目列表（每首包含曲名、作曲家、时期）
:::

:::step{purpose="{{term:computed}} 自动从数据派生新值。根据用户选择的时期筛选曲目列表，切换时期时列表自动更新。这是声明式数据处理的核心模式——你描述筛选规则，{{term:Vue}} 自动执行。" expected="点击不同时期按钮，列表自动过滤，筛选计数同步更新。"}
【基础2】用 {{term:computed}} 实现按时期筛选
:::

:::step{purpose="{{term:v-model}} 双向绑定让表单开发变得极其简洁。输入框的值自动同步到数据，提交后新曲目出现在列表中。整个过程不需要一个 {{term:addEventListener}}。" expected="填写曲名、作曲家、时期后点击添加，新曲目出现在列表中。"}
【基础3】用 {{term:v-model}} + 表单实现添加新曲目
:::

:::step{purpose="{{term:watch}} 监听数据变化自动保存到 {{term:localStorage}}，onMounted 时从 {{term:localStorage}} 恢复数据。数据持久化是真实应用的基本需求，{{term:watch}} + {{term:localStorage}} 是最简洁的实现方案。" expected="添加/删除曲目后刷新页面，数据完整保留。"}
【基础4】用 {{term:localStorage}} 持久化数据（刷新不丢失）
:::

:::step{purpose="{{term:组件}}化是 {{term:Vue}} 工程化的核心实践。将卡片逻辑从 App{{term:.vue}} 中提取为独立{{term:组件}}，通过 {{term:props}} 传入数据，通过 {{term:emits}} 回传{{term:事件}}。这验证你对{{term:组件}}通信模式的掌握。" expected="MusicCard{{term:.vue}} {{term:组件}}可复用，通过 {{term:props}} 接收曲目数据，通过 {{term:emits}} 发送{{term:事件}}。"}
【进阶5】把卡片提取成 MusicCard{{term:.vue}} {{term:组件}}（{{term:props}} + {{term:emits}}）
:::

:::step{purpose="{{term:emit}} {{term:事件}}让子{{term:组件}}通知父{{term:组件}}执行数据变更。收藏功能是一个典型的子{{term:组件}}触发、父{{term:组件}}处理的场景，综合运用了 {{term:props}}（传入收藏状态）和 {{term:emits}}（传出切换{{term:事件}}）。" expected="点击卡片上的收藏按钮，收藏状态切换（❤️/🤍），数据持久化到 {{term:localStorage}}。"}
【进阶6】添加收藏/取消收藏功能
:::

:::step{purpose="删除功能验证了你对 {{term:Vue}} {{term:响应式}}{{term:数组}}操作的理解。使用 {{term:filter}} 返回新{{term:数组}}（而非直接修改原{{term:数组}}），确保{{term:响应式}}系统能正确检测变化并更新 {{term:DOM}}。" expected="点击删除按钮，对应的曲目从列表中消失，{{term:localStorage}} 同步更新。"}
【进阶7】添加删除曲目功能
:::

:::step{purpose="版本管理是专业开发者的基本素养。将项目拆分为有意义的提交（如初始化 {{term:Vue}} 项目、实现曲目列表和筛选、添加持久化功能），每个 {{term:commit}} 都有清晰的描述。这不仅是项目管理的需要，也是展示你工程化思维的窗口。" expected="git log 显示至少 3 个有意义的 {{term:commit}}，每个都有清晰的 {{term:commit}} message。"}
【进阶8】用 {{term:Git}} 管理版本（至少 3 次 {{term:commit}}）
:::

:::step{purpose="{{term:部署}}是将代码变成真正的在线应用的最后一步。用 {{term:npm}} run build {{term:构建}}生产版本，配置 vite.{{term:config}}.js 的 base 路径，推送到 gh-pages 分支。你的作品不再只是本地文件——而是互联网上任何人都能访问的网址。" expected="在浏览器中访问 {{term:GitHub Pages}} URL，能看到你完整的音乐收藏管理器在线运行。"}
【进阶9】{{term:部署}}到 {{term:GitHub Pages}}
:::

箭头{{term:函数}}是 `function` 的简写版：
```js
// 旧写法
const double = function(x) {
  return x * 2
}
// 箭头函数
const double = x => x * 2
// 多行逻辑用花括号
const greet = name => {
  const message = '你好，' + name
  return message
}
```箭头{{term:函数}}就像用连音线简化了分散的音符——同样的旋律，更干净的记谱。
**重要区别：箭头{{term:函数}}没有自己的 `this`。** 普通{{term:函数}}中的 `this` 取决于谁调用了它，而箭头{{term:函数}}的 `this` 继承自定义它的外{{term:层}}{{term:作用域}}。这在{{term:事件}}处理中尤其需要注意。

`...` 像一只手，可以把{{term:数组}}/对象"展开"：
```js
// 合并数组
const classical = ['巴赫', '莫扎特']
const romantic = ['肖邦', '李斯特']
const all = [...classical, ...romantic]
// ['巴赫', '莫扎特', '肖邦', '李斯特']
// 复制对象并修改
const piece = { name: '月光', composer: '贝多芬' }
const updated = { ...piece, period: '古典主义' }
```就像把两个乐团的乐手合并成一个更大的乐团——不改变原来的，创造一个新的。

:::step{purpose="解构赋值让你一行代码取出多个{{term:属性}}，避免重复写 instrument.{{term:name}}、instrument.family。就像从谱架上一次取下三本乐谱，而不是一本一本拿——整齐又高效，也让代码意图更清晰。" expected="控制台输出 {{term:name}}、family、{{term:range}} 三个{{term:变量}}的正确值（小提琴、弦乐、G3-E6）。"}
用解构赋值 {{term:const}} { {{term:name}}, family, {{term:range}} } = instrument 从对象中取出三个{{term:属性}}
:::

:::step{purpose="箭头{{term:函数}}省略了 {{term:function}} 关键字，代码更短；{{term:模板字符串}}使用反引号和 ${} 插值，告别了繁琐的字符串拼接。这是现代 {{term:JavaScript}} 最常用的两种语法，几乎每一个项目中都会大量使用。" expected="describe(instrument) 返回\"小提琴 是弦乐器，音域 G3-E6\"，输出与原始 {{term:function}} 版本一致。"}
用箭头{{term:函数}}重写 describe {{term:函数}}，并用{{term:模板字符串}}（反引号）返回格式化的描述文字
:::

:::step{purpose="展开运算符创建新对象而不修改原对象——这是{{term:函数}}式编程的重要理念：不改变原始数据。就像用一份乐谱复印本做标注，原件保持不变，随时可以回到最初版本。" expected="新对象包含原 instrument 的所有{{term:属性}}（{{term:name}}, family, {{term:range}}）加上 players {{term:属性}}，而原 instrument 对象保持不变。"}
用展开运算符 { ...instrument, players: "40人" } 给 instrument 对象添加新{{term:属性}}
:::

