let highlightBtn = document.querySelector("#highlightBtn");
let clearBtn = document.querySelector("#clearBtn");
let filterBtn = document.querySelector("#filterBtn");
let showAllBtn = document.querySelector("#showAllBtn");
let cards = document.querySelectorAll(".card");
// 高亮全部
highlightBtn.addEventListener("click", function() {
  cards.forEach(function(card) {
    card.classList.add("highlighted");
  });
});
// 取消高亮
clearBtn.addEventListener("click", function() {
  cards.forEach(function(card) {
    card.classList.remove("highlighted");
  });
});
// 只看弦乐（隐藏非弦乐）
filterBtn.addEventListener("click", function() {
  cards.forEach(function(card) {
    if (!card.classList.contains("strings")) {
      card.classList.add("hidden");
    }
  });
});
// 显示全部
showAllBtn.addEventListener("click", function() {
  cards.forEach(function(card) {
    card.classList.remove("hidden");
  });
});

body.content:
基本结构：
```js
try {
  // 尝试执行可能有风险的代码
  const data = JSON.parse(userInput)
  console.log('解析成功：', data)
} catch (error) {
  // 如果出错，在这里处理
  console.log('解析失败，请输入合法的 JSON')
  console.log('错误详情：', error.message)
}
```**{{term:try}}** 说"试试这段代码"。**{{term:catch}}** 说"如果出错了，执行这段"。
就像排练时你标记出可能出错的地方，想好补救方案。

有时候你需要主动抛出错误：
```js
function setVolume(level) {
  if (level < 0 || level > 100) {
    throw new Error('音量必须在 0-100 之间')
  }
  console.log('音量设置为：' + level)
}
try {
  setVolume(150)  // 这会触发错误
} catch (e) {
  console.log('设置失败：' + e.message)
}
````throw` 就像指挥突然停下乐队："不对，长号声音太大了！"——主动发现并指出问题。

`localStorage` 读取时经常出错（数据损坏、格式不对）：
```js
function loadCollection() {
  try {
    const raw = localStorage.getItem('my-collection')
    if (!raw) return []  // 没有数据，返回空数组
    const data = JSON.parse(raw)
    if (!Array.isArray(data)) throw new Error('数据格式错误')
    return data
  } catch (e) {
    console.log('读取收藏失败，已重置：', e.message)
    return []  // 出错就返回空数组，程序不崩溃
  }
}
```这就是"防御性编程"——假设任何可能出错的地方都会出错，提前做好准备。

:::step{purpose="{{term:JSON.parse}} 是常见的\"炸弹\"——传入非法字符串就直接报错崩溃。{{term:try/catch}} 就是防爆服：把可能爆炸的代码放在 {{term:try}} 里，一旦炸了，{{term:catch}} 会接住它而不是让整个程序崩溃。" expected="传入合法 {{term:JSON}} 字符串时，返回解析后的 {{term:JS}} 对象——与直接调用 {{term:JSON.parse}} 的行为一致。"}
用 {{term:try}} 包裹 {{term:JSON.parse}}(str) 的调用，将解析结果赋值给一个{{term:变量}}并返回
:::

:::step{purpose="{{term:catch}} 不只是\"吞掉\"错误，还可以把错误信息包装成友好的格式返回给调用者。这样调用者不需要 {{term:try/catch}}，直接检查返回值的 error {{term:属性}}就知道是否出错了。这是\"防御性编程\"的核心思想。" expected="传入非法 {{term:JSON}} 字符串时，返回 { error: {{term:true}}, message: \"Unexpected {{term:token}}...\" } 而不是报错崩溃。"}
在 {{term:catch}} 块中返回 { error: {{term:true}}, message: error.message }——描述发生了什么错误
:::

:::step{purpose="测试两条分支（成功路径和失败路径）是确保 {{term:try/catch}} 正确实现的关键。就像排练时既练习正常演奏流程，也演练弦断了怎么办——两条路径都验证过，你的代码才算可靠。" expected="控制台分别输出解析成功的对象和包含 error: {{term:true}} 的错误对象，程序没有崩溃。"}
分别传入合法 {{term:JSON}}（{"{{term:name}}": "月光", "composer": "贝多芬"}）和非法 {{term:JSON}}（"这不是{{term:JSON}}"），测试两种路径
:::

```js
function safeParse(str) {
  try {
    const result = JSON.parse(str)
    return result  // 成功则返回解析结果
  } catch (e) {
    return { error: true, message: e.message }  // 失败返回错误对象
  }
}
```

